71	// grokHome returns Grok's base directory, honoring the GROK_HOME override the
72	// E2E runner relies on for isolation.
73	func grokHome() (string, error) {
74		if override := os.Getenv("GROK_HOME"); override != "" {
75			return override, nil
76		}
77		home, err := os.UserHomeDir()
78		if err != nil {
79			return "", fmt.Errorf("failed to get home directory: %w", err)
80		}
