84	// GetSessionDir returns the directory holding this repo's Grok sessions.
85	//
86	// Grok groups sessions by working directory, naming the group with the
87	// URL-encoded absolute path — every character escaped, separators included, so
88	// "/a/b" becomes "%2Fa%2Fb". Verified against a live session.
89	//
90	// Grok switches to a slug-plus-hash name (recording the real path in a .cwd
91	// file inside the group) once the encoded name would exceed 255 bytes. That
92	// branch is not reproduced here: every hook payload except session_start
93	// carries transcriptPath outright, so this path is a fallback rather than the
94	// primary resolution route.
95	func (g *GrokAgent) GetSessionDir(repoPath string) (string, error) {
96		home, err := grokHome()
97		if err != nil {
98			return "", err
99		}
100		abs, err := filepath.Abs(repoPath)
101		if err != nil {
102			abs = repoPath
103		}
104		return filepath.Join(home, "sessions", encodeCWD(abs)), nil
105	}
