117	// encodeCWD percent-encodes every byte url.QueryEscape would, but with "/"
118	// escaped and " " rendered as %20 rather than "+", matching what Grok writes.
119	func encodeCWD(path string) string {
120		escaped := url.PathEscape(path)
121		// PathEscape leaves "/" and a few sub-delims alone; Grok escapes them.
122		var out []byte
123		for i := range len(escaped) {
124			switch c := escaped[i]; c {
125			case '/':
126				out = append(out, '%', '2', 'F')
127			default:
128				out = append(out, c)
129			}
130		}
131		return string(out)
132	}
