134	// ResolveSessionFile returns the transcript path for a session.
135	// Grok stores it as <sessionDir>/<session-id>/updates.jsonl.
136	func (g *GrokAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
137		return filepath.Join(sessionDir, agentSessionID, transcriptFileName)
138	}
