140	// transcriptFileName is Grok's authoritative conversation log. The sibling
141	// chat_history.jsonl holds raw model-facing messages and is deliberately not
142	// used: updates.jsonl is what the docs call the source of truth and what
143	// /resume replays.
144	const transcriptFileName = "updates.jsonl"
