146	// ReadTranscript reads the raw JSONL transcript bytes for a session.
147	func (g *GrokAgent) ReadTranscript(sessionRef string) ([]byte, error) {
148		data, err := os.ReadFile(sessionRef) //nolint:gosec // path comes from Grok hook input
149		if err != nil {
150			return nil, fmt.Errorf("failed to read transcript: %w", err)
151		}
152		return data, nil
153	}
154	
155	// ChunkTranscript splits the JSONL transcript at line boundaries.
156	func (g *GrokAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
157		chunks, err := agent.ChunkJSONL(content, maxSize)
158		if err != nil {
159			return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
160		}
161		return chunks, nil
162	}
163	
164	// ReassembleTranscript concatenates JSONL chunks.
165	func (g *GrokAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
166		return agent.ReassembleJSONL(chunks), nil
167	}
