169	// ReadSession reads a session from Grok's storage.
170	func (g *GrokAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
171		if input.SessionRef == "" {
172			return nil, errors.New("session reference (transcript path) is required")
173		}
174		data, err := os.ReadFile(input.SessionRef)
175		if err != nil {
176			return nil, fmt.Errorf("failed to read transcript: %w", err)
177		}
178		files, _ := modifiedFilesFrom(data, 0)
179		return &agent.AgentSession{
180			SessionID:     input.SessionID,
181			AgentName:     g.Name(),
182			SessionRef:    input.SessionRef,
183			StartTime:     time.Now(),
184			NativeData:    data,
185			ModifiedFiles: files,
186		}, nil
187	}
188	
189	// WriteSession writes a session back to Grok's storage for resumption.
190	func (g *GrokAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
191		if session == nil {
192			return errors.New("session is nil")
193		}
194		if session.AgentName != "" && session.AgentName != g.Name() {
195			return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, g.Name())
196		}
197		if session.SessionRef == "" {
198			return errors.New("session reference (transcript path) is required")
199		}
200		if len(session.NativeData) == 0 {
201			return errors.New("session has no native data to write")
202		}
203		if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
204			return fmt.Errorf("failed to create session dir: %w", err)
205		}
206		if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
207			return fmt.Errorf("failed to write transcript: %w", err)
208		}
209		return nil
210	}
