1	package grok
2	
3	import (
4		"bufio"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9	
10		"github.com/entireio/cli/cmd/entire/cli/agent"
11	)
12	
13	// GetTranscriptPosition returns the line count of a Grok transcript.
14	// updates.jsonl is JSONL, so position is lines.
15	func (g *GrokAgent) GetTranscriptPosition(path string) (int, error) {
16		if path == "" {
17			return 0, nil
18		}
19		file, err := os.Open(path) //nolint:gosec // path comes from Grok transcript location
20		if err != nil {
21			if os.IsNotExist(err) {
22				return 0, nil
23			}
24			return 0, fmt.Errorf("failed to open transcript file: %w", err)
25		}
26		defer file.Close()
27	
28		reader := bufio.NewReader(file)
29		lines := 0
30		for {
31			line, err := reader.ReadBytes('\n')
32			if err != nil {
33				if err == io.EOF {
34					if len(line) > 0 {
35						lines++
36					}
37					break
38				}
39				return 0, fmt.Errorf("failed to read transcript: %w", err)
40			}
41			lines++
42		}
43		return lines, nil
44	}
45	
46	// ExtractModifiedFilesFromOffset returns files Grok changed after startOffset
47	// lines, along with the transcript's current line count.
48	func (g *GrokAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
49		if path == "" {
50			return nil, 0, nil
51		}
52		data, err := os.ReadFile(path) //nolint:gosec // path comes from Grok transcript location
53		if err != nil {
54			if os.IsNotExist(err) {
55				return nil, 0, nil
56			}
57			return nil, 0, fmt.Errorf("failed to open transcript file: %w", err)
58		}
59		found, lines := modifiedFilesFrom(data, startOffset)
60		return found, lines, nil
61	}
62	
63	// modifiedFilesFrom walks the transcript from startOffset and returns the
64	// deduplicated set of files Grok wrote, plus the total line count.
65	//
66	// A `diff` content block on a tool_call_update is the authoritative signal that
67	// a file changed: it is emitted only for an actual edit and carries the
68	// absolute path. locations[] is the fallback — it is present on the same
69	// updates but holds a repo-relative path, and read-only tools populate it too,
70	// so it is consulted only when no diff block named a path for that tool call.
71	func modifiedFilesFrom(data []byte, startOffset int) ([]string, int) {
72		var (
73			out      []string
74			seen     = map[string]bool{}
75			lineNum  int
76			fallback = map[string][]string{} // toolCallID -> relative paths
77			diffed   = map[string]bool{}     // toolCallID -> saw a diff block
78		)
79	
80		add := func(p string) {
81			if p == "" || seen[p] {
82				return
83			}
84			seen[p] = true
85			out = append(out, p)
86		}
87	
88		for _, raw := range splitJSONL(data) {
89			lineNum++
90			if lineNum <= startOffset {
91				continue
92			}
93			var line transcriptLine
94			if err := json.Unmarshal(raw, &line); err != nil {
95				continue // skip malformed lines
96			}
97			u := line.Params.Update
98			if u.SessionUpdate != "tool_call_update" && u.SessionUpdate != "tool_call" {
99				continue
100			}
101			for _, c := range u.diffBlocks() {
102				if c.Type == "diff" && c.Path != "" {
103					diffed[u.ToolCallID] = true
104					add(c.Path)
105				}
106			}
107			for _, l := range u.Locations {
108				if l.Path != "" {
109					fallback[u.ToolCallID] = append(fallback[u.ToolCallID], l.Path)
110				}
111			}
112		}
113	
114		for id, paths := range fallback {
115			if diffed[id] {
116				continue
117			}
118			for _, p := range paths {
119				add(p)
120			}
121		}
122	
123		// Count any lines before startOffset that the loop skipped.
124		return out, lineNum
125	}
126	
127	// splitJSONL splits raw JSONL into non-empty lines.
128	func splitJSONL(data []byte) [][]byte {
129		var out [][]byte
130		start := 0
131		for i := range data {
132			if data[i] != '\n' {
133				continue
134			}
135			if line := trimCR(data[start:i]); len(line) > 0 {
136				out = append(out, line)
137			}
138			start = i + 1
139		}
140		if start < len(data) {
141			if line := trimCR(data[start:]); len(line) > 0 {
142				out = append(out, line)
143			}
144		}
145		return out
146	}
147	
148	func trimCR(b []byte) []byte {
149		if len(b) > 0 && b[len(b)-1] == '\r' {
150			b = b[:len(b)-1]
151		}
152		return b
153	}
154	
155	// CalculateTokenUsage sums the turn_completed usage blocks after fromOffset.
156	//
157	// Grok reports inputTokens as the TOTAL input, cache inclusive, so the fresh
158	// portion is derived here — the same shape Cursor needs. Verified against the
159	// headless JSON summary for the same turn, which reports the fresh figure
160	// directly.
161	func (g *GrokAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
162		var (
163			total    agent.TokenUsage
164			lineNum  int
165			sawUsage bool
166		)
167		for _, raw := range splitJSONL(transcriptData) {
168			lineNum++
169			if lineNum <= fromOffset {
170				continue
171			}
172			var line transcriptLine
173			if err := json.Unmarshal(raw, &line); err != nil {
174				continue
175			}
176			u := line.Params.Update
177			if u.SessionUpdate != "turn_completed" || u.Usage == nil {
178				continue
179			}
180			sawUsage = true
181			fresh := u.Usage.InputTokens - u.Usage.CachedReadTokens - u.Usage.CacheCreationTokens
182			if fresh < 0 {
183				fresh = 0
184			}
185			total.InputTokens += fresh
186			total.CacheReadTokens += u.Usage.CachedReadTokens
187			total.CacheCreationTokens += u.Usage.CacheCreationTokens
188			total.OutputTokens += u.Usage.OutputTokens
189			calls := u.Usage.ModelCalls
190			if calls == 0 {
191				calls = 1
192			}
193			total.APICallCount += calls
194		}
195		if !sawUsage {
196			return nil, nil //nolint:nilnil // no usage data is "unknown", not zero
197		}
198		return &total, nil
199	}
200	
201	// ExtractModel returns the model Grok used, read from the per-message _meta
202	// Grok stamps on message chunks. Hook payloads carry no model field, so the
203	// transcript is the only source.
204	func (g *GrokAgent) ExtractModel(transcriptData []byte) (string, error) {
205		for _, raw := range splitJSONL(transcriptData) {
206			var line transcriptLine
207			if err := json.Unmarshal(raw, &line); err != nil {
208				continue
209			}
210			if m := line.Params.Update.Meta.ModelID; m != "" {
211				return m, nil
212			}
213		}
214		return "", nil
215	}

