19		// Cursor is rate-limited ("Increase limits for faster responses"), so gate
20		// its parallelism. Without a registered gate, AcquireSlot is a no-op and the
21		// E2E_CONCURRENT_TEST_LIMIT override the workflow sets has no effect.
22		RegisterGate("cursor-cli", 2)
23	}
24	
25	// CursorCLI implements the E2E Agent interface for the Cursor Agent CLI binary.
26	// The CLI binary is called "agent" and uses Cursor's hooks system via
27	// .cursor/hooks.json. It maps to the same Entire agent as Cursor IDE ("cursor").
28	//
29	// All E2E interactions use interactive (tmux) mode so that the full hook
30	// lifecycle fires (sessionStart, beforeSubmitPrompt, stop, sessionEnd).
31	// Headless (-p) mode skips beforeSubmitPrompt and stop hooks.
32	type CursorCLI struct{}
33	
34	func (a *CursorCLI) Name() string               { return "cursor-cli" }
35	func (a *CursorCLI) Binary() string             { return "agent" }
36	func (a *CursorCLI) EntireAgent() string        { return "cursor" }
37	func (a *CursorCLI) TimeoutMultiplier() float64 { return 1.5 }
38	
39	// PromptPattern returns a regex matching Cursor's ready-state prompt markers.
40	// Cursor has used multiple startup/completion markers across releases.
41	func (a *CursorCLI) PromptPattern() string {
42		return `(/ commands|Plan, search, build anything|Add a follow-up)`
43	}
44	
45	func (a *CursorCLI) IsTransientError(out Output, err error) bool {
46		if err == nil {
47			return false
48		}
49		if errors.Is(err, context.DeadlineExceeded) {
50			return true
51		}
52		combined := out.Stdout + out.Stderr
53		for _, p := range []string{
54			"overloaded",
55			"rate limit",
56			"429",
57			"503",
58			"529",
59			"ECONNRESET",
60			"ETIMEDOUT",
61			"server error",
62			"Internal Server Error",
63		} {
64			if strings.Contains(combined, p) {
65				return true
66			}
67		}
68		return false
69	}
70	
71	func (a *CursorCLI) Bootstrap() error {
72		if err := a.verifyBinaryIsCursor(); err != nil {
73			return err
74		}
75		// The Cursor CLI authenticates via CURSOR_API_KEY env var or OAuth.
76		// On CI, ensure CURSOR_API_KEY is set. Locally, OAuth/keychain works.
77		if os.Getenv("CI") != "" && os.Getenv("CURSOR_API_KEY") == "" {
78			return errors.New("CURSOR_API_KEY must be set on CI for cursor-cli E2E tests")
79		}
80		return nil
81	}
82	
83	// verifyBinaryIsCursor guards against another tool owning the name "agent".
84	//
85	// Cursor's CLI binary is called `agent`, which is not a name it has to itself:
86	// xAI's Grok installer symlinks both `grok` and `agent` into ~/.local/bin. On a
87	// machine with both, whichever wins $PATH decides what this leg actually runs,
88	// and preflight only does LookPath("agent") — so it passes either way and the
89	// suite would exercise Grok while reporting Cursor. Silently testing the wrong
90	// agent is worse than failing, so fail loudly and name the fix.
91	func (a *CursorCLI) verifyBinaryIsCursor() error {
92		path, err := exec.LookPath(a.Binary())
93		if err != nil {
94			return nil // preflight already reports a missing binary
95		}
96		ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
97		defer cancel()
98	
99		out, err := exec.CommandContext(ctx, path, "--version").CombinedOutput()
100		if err != nil {
101			// A version probe that fails proves nothing either way; leave the
102			// verdict to the tests rather than blocking on a flaky exec.
103			return nil // an inconclusive probe must not fail the suite
104		}
105		if v := strings.ToLower(string(out)); strings.Contains(v, "grok") {
106			return fmt.Errorf(
107				"%q resolves to Grok, not the Cursor CLI (%s reported %q).\n"+
108					"xAI's installer symlinks `agent` alongside `grok`. Put Cursor's `agent` "+
109					"earlier in $PATH, or run the Grok leg instead with --agent grok",
110				a.Binary(), path, strings.TrimSpace(string(out)))
111		}
112		return nil
113	}
114	
115	// cursorConfigDir creates an isolated per-session config directory for the
116	// Cursor CLI. Each session gets its own XDG_CONFIG_HOME so that parallel tests
117	// don't race on the shared ~/.config/cursor/cli-config.json file.
118	// The directory is pre-seeded with an empty cli-config.json to avoid the
119	// atomic temp-file rename that triggers the ENOENT race.
120	func cursorConfigDir() (string, error) {
121		tmp, err := os.MkdirTemp("", "cursor-e2e-config-*")
122		if err != nil {
123			return "", fmt.Errorf("create temp config dir: %w", err)
124		}
125		cursorDir := filepath.Join(tmp, "cursor")
126		if err := os.MkdirAll(cursorDir, 0o755); err != nil {
127			return "", fmt.Errorf("mkdir cursor config: %w", err)
128		}
129		if err := os.WriteFile(filepath.Join(cursorDir, "cli-config.json"), []byte("{}"), 0o644); err != nil {
130			return "", fmt.Errorf("seed cli-config.json: %w", err)
131		}
132		return tmp, nil
133	}
